import requests
base='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
qs=['"well-controlled HbA1c" continuous glucose monitoring cardiovascular','glycemic variability cardiovascular risk diabetes CGM HbA1c','continuous glucose monitoring 10-year cardiovascular risk diabetes']
for q in qs:
 d=requests.get(base,params={'db':'pubmed','term':q,'retmode':'json','retmax':10},timeout=20).json()['esearchresult']
 print('\nQUERY',q,'COUNT',d['count'],'IDS',d['idlist'])
 if d['idlist']:
  xml=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(d['idlist']),'retmode':'json'},timeout=20).json()['result']
  for i in d['idlist']:
   x=xml[i]; print(i,x.get('title'),x.get('pubdate'))

import requests, xml.etree.ElementTree as ET
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi'
r=requests.get(u,params={'db':'pubmed','id':'27502250','retmode':'xml'},timeout=20)
root=ET.fromstring(r.text)
for el in root.findall('.//ArticleTitle'): print('TITLE:', ''.join(el.itertext()))
for el in root.findall('.//Abstract/AbstractText'):
 print('ABSTRACT',el.attrib.get('Label',''),':',''.join(el.itertext()))
for el in root.findall('.//AuthorList/Author'):
 ln=el.findtext('LastName'); ini=el.findtext('Initials');
 if ln: print('AUTHOR:',ln,ini)
print('JOURNAL:',root.findtext('.//Journal/Title'),'YEAR:',root.findtext('.//PubDate/Year'),'PMID:27502250')
